CREATE TABLE "NotificationChannel" ("id" TEXT NOT NULL, "memberId" TEXT NOT NULL, "provider" TEXT NOT NULL, "externalUserId" TEXT NOT NULL, "externalChatId" TEXT, "isVerified" BOOLEAN NOT NULL DEFAULT false, "isEnabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "NotificationChannel_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationPreference" ("id" TEXT NOT NULL, "memberId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "telegramEnabled" BOOLEAN NOT NULL DEFAULT true, "baleEnabled" BOOLEAN NOT NULL DEFAULT true, "inAppEnabled" BOOLEAN NOT NULL DEFAULT true, "quietHoursEnabled" BOOLEAN NOT NULL DEFAULT false, "quietHoursStart" TEXT, "quietHoursEnd" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "NotificationPreference_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationOutbox" ("id" TEXT NOT NULL, "eventType" TEXT NOT NULL, "aggregateType" TEXT NOT NULL, "aggregateId" TEXT NOT NULL, "memberId" TEXT NOT NULL, "provider" TEXT NOT NULL, "recipientId" TEXT NOT NULL, "payload" JSONB NOT NULL, "idempotencyKey" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "attemptCount" INTEGER NOT NULL DEFAULT 0, "nextAttemptAt" TIMESTAMP(3), "sentAt" TIMESTAMP(3), "failedAt" TIMESTAMP(3), "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "NotificationOutbox_pkey" PRIMARY KEY ("id"));
CREATE TABLE "NotificationLog" ("id" TEXT NOT NULL, "outboxId" TEXT, "provider" TEXT NOT NULL, "recipientId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "status" TEXT NOT NULL, "providerMessageId" TEXT, "errorCode" TEXT, "errorMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "NotificationLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AccountLinkCode" ("id" TEXT NOT NULL, "memberId" TEXT NOT NULL, "provider" TEXT NOT NULL, "codeHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdByIp" TEXT, "attemptCount" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "AccountLinkCode_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProcessedProviderUpdate" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "providerUpdateId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProcessedProviderUpdate_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "NotificationChannel_provider_externalUserId_key" ON "NotificationChannel"("provider", "externalUserId");
