CREATE INDEX "NotificationLog_provider_recipientId_createdAt_idx" ON "NotificationLog"("provider", "recipientId", "createdAt");
CREATE INDEX "NotificationLog_outboxId_idx" ON "NotificationLog"("outboxId");
CREATE UNIQUE INDEX "AccountLinkCode_codeHash_key" ON "AccountLinkCode"("codeHash");
